(()=>{
const pick=(el)=>{if(!el)return null;const c=getComputedStyle(el),r=el.getBoundingClientRect();return {cls:el.className&&el.className.baseVal===undefined?String(el.className).slice(0,60):'',tag:el.tagName,txt:(el.innerText||el.value||el.placeholder||'').trim().slice(0,30),h:Math.round(r.height),w:Math.round(r.width),font:c.fontSize+'/'+c.lineHeight+' '+c.fontWeight+' '+c.fontFamily.split(',')[0],color:c.color,bg:c.backgroundColor,border:c.borderTopWidth+' '+c.borderTopColor,radius:c.borderTopLeftRadius,pad:c.padding,shadow:c.boxShadow.slice(0,50),gap:c.gap,ls:c.letterSpacing}};
const main=document.querySelector('main')||document.body;
const card=[...main.querySelectorAll('*')].find(e=>/tab/i.test(e.className)&&e.querySelector('button'));
const out={};
const tabs=main.querySelector('.tabs, .tab-bar, [role=tablist]');
out.tablist=pick(tabs);
if(tabs){const b=[...tabs.querySelectorAll('button,a')];out.tabOn=pick(b.find(x=>/active|on|sel/.test(x.className)||x.getAttribute('aria-selected')==='true'));out.tabOff=pick(b.find(x=>!(/active|on|sel/.test(x.className)||x.getAttribute('aria-selected')==='true')));const cnt=b[0].querySelector('span,b,em,small');out.tabCount=pick(cnt);out.tabsParent=pick(tabs.parentElement)}
const search=main.querySelector('input[type=search], .input-search input, input[placeholder^=Szukaj]');out.search=pick(search);out.searchWrap=pick(search&&search.parentElement);
const sel=main.querySelector('.cs-btn');out.select=pick(sel);
const seg=main.querySelector('.segmented, .seg, .view-toggle, [role=radiogroup], .tt-seg');out.seg=pick(seg);if(seg){const bs=[...seg.querySelectorAll('button')];out.segOn=pick(bs.find(x=>/active|on/.test(x.className)||x.getAttribute('aria-pressed')==='true'||x.getAttribute('aria-checked')==='true'));out.segOff=pick(bs.find(x=>!(/active|on/.test(x.className)||x.getAttribute('aria-pressed')==='true'||x.getAttribute('aria-checked')==='true')))}
const row=search&&search.closest('div[class*=bar], div[class*=tool], div[class*=filter]');out.toolbar=pick(row);
return out})()

